ns', 'Prospective Studies', 'Psilocybin/therapeutic use', 'Psychedelics', 'anxiety', 'depression', 'mystical experience', 'psilocybin']	10.1177/02698811221101061	2022		\N	https://pubmed.ncbi.nlm.nih.gov/35924888/	1
